/* ==================================================================
   fix-demo-text.js — repairs demo rows that were seeded with placeholder
   copy, in place, without re-seeding.

   Two things it fixes:

   1. Every seeded task's description was the literal string
      "Demo record generated by scripts/seed-demo.js." — a developer note
      showing to clients and to anyone being given a demo.
   2. Review comments were picked from one flat pool regardless of the stars,
      so a one-star review could read "Fixed in under an hour. Brilliant."

   Re-seeding would fix both but would renumber every task, so this updates the
   existing rows instead. It is idempotent and safe to re-run: descriptions are
   only rewritten where they still hold the placeholder, and a comment is only
   replaced when it sits in the wrong band for its rating. Rows whose text is
   not recognised as seeded demo copy are never touched, so real user-authored
   tasks and reviews are left alone.

   Usage:
       node scripts/fix-demo-text.js              # local digit.db
       node scripts/fix-demo-text.js --dry-run    # report, change nothing
       DATABASE_URL=libsql://... DATABASE_AUTH_TOKEN=... node scripts/fix-demo-text.js
================================================================== */
const fs = require('fs');
const path = require('path');
const { createClient } = require('@libsql/client');

/* Load .env.local / .env the same way scripts/push-to-remote.js does, so a
   `vercel env pull` is enough to point this at production. */
for (const f of ['.env.local', '.env']) {
  const p = path.join(__dirname, '..', f);
  if (!fs.existsSync(p)) continue;
  for (const line of fs.readFileSync(p, 'utf8').split(/\r?\n/)) {
    const m = line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.*)\s*$/i);
    if (!m) continue;
    let v = m[2].trim();
    if ((v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"))) v = v.slice(1, -1);
    if (!(m[1] in process.env)) process.env[m[1]] = v;
  }
}

const DRY = process.argv.includes('--dry-run');
const content = require('./demo-content.json');

const PLACEHOLDER = 'Demo record generated by scripts/seed-demo.js.';
const DESC = Object.fromEntries(content.tasks.map(t => [t.en, t.d_en]));

const BANDS = {
  high: content.comments.high.map(c => c.en),
  mid: content.comments.mid.map(c => c.en),
  low: content.comments.low.map(c => c.en),
};
const bandFor = (stars) => stars >= 4 ? 'high' : stars === 3 ? 'mid' : 'low';
/* Every string the seed has ever used as a comment. Anything outside this set is
   a real person's words and is left untouched. */
const KNOWN = new Set([
  ...BANDS.high, ...BANDS.mid, ...BANDS.low,
  // the original flat pool, including the entries no longer used
  'Fast and friendly, explained everything clearly.', 'Fixed in under an hour. Brilliant.',
  'Very patient with someone who is not technical at all.', 'Sorted it remotely, no fuss.',
  'Good work, though it took longer than I expected.', 'Knew exactly what the problem was.',
  'Polite and thorough. Would use again.',
]);

/* Deterministic choice keyed on the task id, so the local and the hosted
   database land on the same comment and repeated runs stay stable. */
function chooseComment(id, stars) {
  const pool = BANDS[bandFor(stars)];
  let h = 2166136261;
  const s = 'c' + id + ':' + stars;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619) >>> 0; }
  return pool[h % pool.length];
}

(async () => {
  const url = process.env.DATABASE_URL || 'file:' + path.join(__dirname, '..', 'digit.db');
  const authToken = process.env.DATABASE_AUTH_TOKEN || undefined;
  const remote = !url.startsWith('file:');
  const db = createClient(authToken ? { url, authToken } : { url });
  console.log(`target: ${remote ? url.replace(/\/\/.*@/, '//') : 'local digit.db'}${DRY ? '  (dry run)' : ''}`);

  const rows = (await db.execute(
    'SELECT id, title, description, rating, rating_comment FROM tasks')).rows;

  const descFixes = [];
  const unknownTitles = new Set();
  for (const r of rows) {
    if (r.description !== PLACEHOLDER) continue;
    // Seeded titles carry the "[demo] " marker that --reset keys on.
    const d = DESC[String(r.title).replace(/^\[demo\]\s*/, '')];
    if (!d) { unknownTitles.add(r.title); continue; }
    descFixes.push({ id: Number(r.id), description: d });
  }

  const commentFixes = [];
  for (const r of rows) {
    const c = r.rating_comment;
    if (c === null || c === '' || r.rating === null) continue;
    if (!KNOWN.has(c)) continue;                       // real review: leave it
    const stars = Number(r.rating);
    if (BANDS[bandFor(stars)].includes(c)) continue;   // already coherent
    commentFixes.push({ id: Number(r.id), stars, from: c, to: chooseComment(Number(r.id), stars) });
  }

  console.log(`tasks: ${rows.length}`);
  console.log(`descriptions still holding the placeholder: ${descFixes.length}`);
  if (unknownTitles.size) {
    console.log(`  ! ${unknownTitles.size} placeholder row(s) whose title is not in demo-content.json, skipped:`);
    [...unknownTitles].slice(0, 8).forEach(t => console.log('      ' + t));
  }
  console.log(`comments that contradict their rating: ${commentFixes.length}`);
  for (const f of commentFixes.slice(0, 8)) {
    console.log(`      #${f.id} ${f.stars}★  "${f.from}"  ->  "${f.to}"`);
  }
  if (commentFixes.length > 8) console.log(`      ... and ${commentFixes.length - 8} more`);

  if (DRY) { console.log('dry run: nothing written'); return; }
  if (!descFixes.length && !commentFixes.length) { console.log('nothing to do'); return; }

  // Batched rather than one round-trip per row: over a hosted database that is
  // the difference between a second and a couple of minutes.
  const stmts = [
    ...descFixes.map(f => ({ sql: 'UPDATE tasks SET description = ? WHERE id = ?', args: [f.description, f.id] })),
    ...commentFixes.map(f => ({ sql: 'UPDATE tasks SET rating_comment = ? WHERE id = ?', args: [f.to, f.id] })),
  ];
  for (let i = 0; i < stmts.length; i += 50) await db.batch(stmts.slice(i, i + 50), 'write');

  console.log(`updated ${descFixes.length} description(s) and ${commentFixes.length} comment(s)`);
})().catch(e => { console.error(e); process.exit(1); });
